      if (__mpx_mode__ !== 'web') return
      this.$nextTick(() => {
        const feedScroll = this.$refs.feedScroll
        if (feedScroll && typeof feedScroll.refresh === 'function') {
          feedScroll.refresh()
        }
      })
    },
    onDragStart (event) {
      this.dragOffset = event.detail.scrollTop
